const trigger_id = $input.all()[0].json.trigger_id;
const email_id = $input.all()[0].json.button_value;
const channel_id = $input.all()[0].json.channel_id;
const message_ts = $input.all()[0].json.original_payload.container.message_ts;
const token = $env.SLACK_BOT_TOKEN;

const view = {
  type: "modal",
  callback_id: "edit_email_modal",
  private_metadata: JSON.stringify({
    email_id: email_id,
    channel_id: channel_id,        // 追加
    message_ts: message_ts         // 追加
  }),
  title: {
    type: "plain_text",
    text: "メール内容編集"
  },
  submit: {
    type: "plain_text",
    text: "保存"
  },
  close: {
    type: "plain_text",
    text: "キャンセル"
  },
  blocks: [
    {
      type: "input",
      block_id: "email_content_block",
      label: {
        type: "plain_text",
        text: "メール内容"
      },
      element: {
        type: "plain_text_input",
        action_id: "email_content_input",
        multiline: true,
        initial_value: $input.all()[0].json.reply_text,
        placeholder: {
          type: "plain_text",
          text: "メールの内容を入力してください"
        }
      }
    }
  ]
};

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://slack.com/api/views.open',
  headers: {
    'Authorization': `Bearer ${token}`,
    'Content-Type': 'application/json; charset=utf-8'
  },
  body: {
    trigger_id: trigger_id,
    view: view
  }
});

return [{ json: response }];

const payload = $input.all()[0].json;

// view_submissionの場合の処理
if (payload.type === 'view_submission') {  
  return [{
    json: {
      id: payload.id,           // {{ $json.id }} に対応
      reply_text: payload.edited_content,  // {{ $json.reply_text }} に対応
      user_id: payload.user_id,
      channel_id: payload.channel_id,
      message_ts: payload.message_ts,
      timestamp: new Date().toISOString()
    }
  }];
}

// view_submissionでない場合は空を返す
return [{ json: {} }];

