// 「データ前処理」ノードからのメールデータを取得
const emailData = $node["データ前処理"].json;
const senderEmail = emailData.From;

// Google Sheetsからのブロックリストを取得（直前のノード）
const blockListRows = $input.all();

// ブロックリストからメールアドレス配列を作成
const blockedEmails = blockListRows
  .map(item => (item.json["ブロックするメールアドレス"] || '').toLowerCase().trim())  // ✅ 正しいフィールド名
  .filter(email => email.length > 0);

// デバッグ用（確認後削除）
console.log('送信者メール:', senderEmail);
console.log('ブロックリスト:', blockedEmails);

// 判定実行
const isBlocked = blockedEmails.includes(senderEmail);

return [{
  json: {
    ...emailData,
    isBlocked: isBlocked,
    blockReason: isBlocked ? `メールアドレス ${senderEmail} がブロックリストに含まれています` : null
  },
  pairedItem: { item: 0, input: 0 }
}];

// Gmail Triggerからのデータを正規化し、空のフィールドにデフォルト値を設定
const gmailData = $input.all()[0].json;
// JSON安全化関数：特殊文字をエスケープ
function sanitizeForJson(text) {
  if (!text) return '';

  return text
    .replace(/\\/g, '\\\\')   // バックスラッシュを最初にエスケープ
    .replace(/"/g, '\\"')     // ダブルクォートをエスケープ
    .replace(/\n/g, '\\n')    // 改行をエスケープ
    .replace(/\r/g, '\\r')    // 復帰文字をエスケープ
    .replace(/\t/g, '\\t')    // タブをエスケープ
    .trim();                  // 前後の空白を削除
}
// デフォルト値を設定した正規化されたデータを作成
const normalizedData = {
  // 元のデータをすべて保持
  ...gmailData,

  // 空の場合にデフォルト値を設定 + JSON安全化
  Subject: sanitizeForJson(gmailData.Subject) || '(件名なし)',
  From: sanitizeForJson(gmailData.From) || '(送信者不明)',
  To: sanitizeForJson(gmailData.To) || '(宛先不明)',
  Body: sanitizeForJson(gmailData.Body || gmailData.TextPlain) || '(本文なし)',
  Date: gmailData.Date || new Date().toISOString(),
  MessageId: gmailData.MessageId || gmailData['Message-ID'] || 'unknown'
};
return [{ json: normalizedData }];

// 前のノードからメールアドレスを取得（検索対象）
const emailData = $input.first().json;
const targetEmail = (emailData.FromEmail || emailData.From || '').toLowerCase().trim();

// Google Sheetsからのパートナーリストを取得
const partnerListRows = $input.all();

// パートナー情報を検索
let partnerName = null;
let partnerId = null;
let lineUserId = null;

for (const row of partnerListRows) {
  const rowData = row.json;
  const partnerEmail = (rowData["メールアドレス"] || '').toLowerCase().trim();

  if (partnerEmail && partnerEmail === targetEmail) {
    partnerName = rowData["パートナー名"] || null;
    partnerId = rowData["row_number"] || null;
    lineUserId = rowData["LineUserID"] || null;
    break; // 一致したら検索終了
  }
}

return [{
  json: {
    ...emailData,
    // パートナー情報を追加
    partnerName: partnerName,
    partnerId: partnerId,
    lineUserId: lineUserId,
    isPartner: partnerName !== null,
    searchEmail: targetEmail
  },
  pairedItem: { item: 0, input: 0 }
}];

// LINEのユーザーIDでパートナー情報を検索
const webhookData = $('Line Webhook Trigger').first().json.body;

// eventsが存在するかチェック
if (!webhookData.events || webhookData.events.length === 0) {
  return { json: { found: false, message: "メッセージイベントがありません" } };
}

// ユーザーIDを取得
const lineUserId = webhookData.events[0].source.userId;

// スプレッドシートのデータを取得
const sheetData = $input.all()[1].json;
const partnerList = Array.isArray(sheetData) ? sheetData : [sheetData];

// 一致するパートナーを探す
const foundPartner = partnerList.find(partner => 
  partner.LineUserID && partner.LineUserID.trim() === lineUserId
);

// 結果を返す
if (foundPartner) {
  return {
    json: {
      found: true,
      partnerName: foundPartner["パートナー名"],
      email: foundPartner["メールアドレス"],
      lineUserId: lineUserId,
      text: $('Line Webhook Trigger').first().json.body.events[0].message.text
    }
  };
} else {
  return {
    json: {
      found: false,
      lineUserId: lineUserId,
      message: "該当するパートナーが見つかりません"
    }
  };
}

// LLMの出力からメールアドレス部分を削除
for (const item of $input.all()) {
  // outputフィールドが存在することを確認
  if (item.json.output) {
    // 正規表現でメールアドレス部分（<email@domain>形式）を削除
    const cleanedOutput = item.json.output.replace(/<[^@]+@[^>]+>/g, '');

    // 連続する半角スペースのみを1つにまとめる（改行は保持）
    const finalOutput = cleanedOutput.replace(/ {2,}/g, ' ').trim();

    // 結果を更新
    item.json.output = finalOutput;
  }
}

return $input.all();

