// LLMの出力からメールアドレス部分を削除
for (const item of $input.all()) {
  // outputフィールドが存在することを確認
  if (item.json.output) {
    // 正規表現でメールアドレス部分（<email@domain>形式）を削除
    const cleanedOutput = item.json.output.replace(/<[^@]+@[^>]+>/g, '');

    // 連続する半角スペースのみを1つにまとめる（改行は保持）
    const finalOutput = cleanedOutput.replace(/ {2,}/g, ' ').trim();

    // 結果を更新
    item.json.output = finalOutput;
  }
}

return $input.all();

// Slackペイロードをパースして構造化
const body = $input.all()[0].json.body;

// payloadが存在しない場合のエラー処理
if (!body.payload) {
  return [{
    json: {
      error: "No payload found",
      originalBody: body
    }
  }];
}

let payload;
try {
  payload = JSON.parse(body.payload);
} catch (error) {
  return [{
    json: {
      error: "Failed to parse payload",
      originalBody: body,
      parseError: error.message
    }
  }];
}

// メッセージ内容抽出の共通関数
function extractMessageContent(messageBlocks) {
  let senderEmail = "";
  let subjectInfo = "";
  let replyText = "";

  if (messageBlocks && messageBlocks.length > 1) {
    // 送信者情報の抽出とクリーンアップ
    if (messageBlocks[1].fields && messageBlocks[1].fields[0]) {
      const rawSender = messageBlocks[1].fields[0].text.split('\n')[1] || "";

      // HTMLエンティティをデコード
      const decodedSender = rawSender
        .replace(/"/g, '')
        .replace(/&lt;/g, '<')
        .replace(/&gt;/g, '>');

      // Slackのmailtoリンク形式を処理: <mailto:email|display>
      const mailtoMatch = decodedSender.match(/<mailto:([^|]+)\|([^>]+)>/);
      if (mailtoMatch) {
        senderEmail = mailtoMatch[1];
      } else {
        // 通常の Name <email@example.com> 形式
        const emailMatch = decodedSender.match(/<([^>]+)>/);
        if (emailMatch) {
          senderEmail = emailMatch[1]; // メールアドレス部分のみ抽出
        } else {
          // メールアドレスのみの場合
          senderEmail = decodedSender.trim();
        }
      }
    }

    // 件名情報の抽出
    if (messageBlocks[1].fields && messageBlocks[1].fields[1]) {
      subjectInfo = messageBlocks[1].fields[1].text.split('\n')[1] || "";
    }

    // 返信テキストの抽出とHTML変換
    if (messageBlocks[2] && messageBlocks[2].text) {
      const fullText = messageBlocks[2].text.text;
      const replyMatch = fullText.match(/返信案:\s*(.*?)\s*$/s);
      let rawReplyText = replyMatch ? replyMatch[1].trim() : "";

      // 不要な部分を削除
      rawReplyText = rawReplyText
        .replace(/^:memo:\s*返信案:\s*/, '')     // 先頭の:memo: 返信案:を削除
        .replace(/^📝\s*返信案:\s*/, '')        // 先頭の📝 返信案:を削除
        .replace(/^返信案:\s*/, '')             // 先頭の返信案:を削除
        .replace(/<mailto:[^>]+>\s*様\s*/g, '') // <mailto:...> 様 を削除
        .trim();

      // 改行をHTMLタグに変換してJSON安全にする
      replyText = rawReplyText
        .replace(/\r\n/g, '\n')           // Windows改行を統一
        .replace(/\r/g, '\n')             // Mac改行を統一
        .split('\n')                      // 改行で分割
        .map(line => line.trim())         // 各行の前後空白削除
        .filter(line => line.length > 0)  // 空行削除
        .map(line => `<p>${line}</p>`)    // 各行をpタグで囲む
        .join('');                        // 結合
    }
  }

  return { senderEmail, subjectInfo, replyText };
}

// 共通のレスポンス構築関数
function buildResponse(baseData, messageContent = {}) {
  return {
    // アクション情報
    action_id: baseData.action_id || null,
    button_value: baseData.button_value || null,
    type: baseData.type || null,

    // ユーザー・チャンネル情報
    user_id: baseData.user_id || null,
    channel_id: baseData.channel_id || null,
    trigger_id: baseData.trigger_id || null,
    response_url: baseData.response_url || null,

    // メッセージ情報
    id: baseData.id || null,
    sender: messageContent.senderEmail || "",
    subject: messageContent.subjectInfo || "",
    reply_text: messageContent.replyText || "",

    // view_submission特有の情報
    edited_content: baseData.edited_content || null,
    callback_id: baseData.callback_id || null,
    message_ts: baseData.message_ts || null,

    // 原本データ（必要時参照用）
    original_payload: baseData.original_payload || null,

    // GmailのURL
    gmail_url: baseData.gmail_url || null,

    // 処理時刻
    processed_at: new Date().toISOString()
  };
}

// ペイロードタイプによる処理分岐
if (payload.type === 'view_submission') {
  // モーダル送信の場合
  const private_metadata = JSON.parse(payload.view.private_metadata);
  const email_id = private_metadata.email_id;
  const channel_id = private_metadata.channel_id;
  const message_ts = private_metadata.message_ts;
  const email_content = payload.view.state.values.email_content_block.email_content_input.value;

  // private_metadataに元のメッセージ情報も含まれている場合は使用
  const messageContent = {
    senderEmail: private_metadata.sender || "",
    subjectInfo: private_metadata.subject || "",
    replyText: private_metadata.reply_text || ""
  };

  const baseData = {
    action_id: "modal_submission",
    type: "view_submission",
    id: email_id,
    edited_content: email_content,
    user_id: payload.user.id,
    callback_id: payload.view.callback_id,
    channel_id: channel_id,
    message_ts: message_ts,
    original_payload: payload
  };

  return [{ json: buildResponse(baseData, messageContent) }];

} else if (payload.type === 'block_actions') {
  // ボタンクリックの場合
  const action = payload.actions && payload.actions[0];
  const messageBlocks = payload.message && payload.message.blocks;

  // メッセージ内容を抽出
  const messageContent = extractMessageContent(messageBlocks);

  const baseData = {
    action_id: action ? action.action_id : null,
    button_value: action ? action.value : null,
    type: "block_actions",
    user_id: payload.user ? payload.user.id : null,
    channel_id: payload.channel ? payload.channel.id : null,
    trigger_id: payload.trigger_id || null,
    response_url: payload.response_url || null,
    id: action ? action.value : null,
    original_payload: payload,
    gmail_url: action && action.value ? 
      `https://mail.google.com/mail/u/0/#inbox/${action.value}` : 
      null
  };

  return [{ json: buildResponse(baseData, messageContent) }];

} else {
  return [{
    json: {
      error: "Unknown payload type",
      type: payload.type,
      original_payload: payload
    }
  }];
}

// Slackペイロードをパースして構造化（LINE対応版）
const body = $input.all()[0].json.body;

// payloadが存在しない場合のエラー処理
if (!body.payload) {
  return [{
    json: {
      error: "No payload found",
      originalBody: body
    }
  }];
}

let payload;
try {
  payload = JSON.parse(body.payload);
} catch (error) {
  return [{
    json: {
      error: "Failed to parse payload",
      originalBody: body,
      parseError: error.message
    }
  }];
}

// LINE用テキスト変換関数
function convertToPlainText(htmlText) {
  if (!htmlText) return "";

  return htmlText
    .replace(/<[^>]*>/g, '') // HTMLタグ削除
    .replace(/&lt;/g, '<') // HTMLエンティティデコード
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .trim();
}

// 通知タイプ判定関数
function getNotificationType(buttonValue) {
  if (!buttonValue) return "unknown";

  try {
    const parsed = JSON.parse(buttonValue);
    return parsed.type || "unknown";
  } catch {
    return "unknown";
  }
}

// LINEデータ抽出関数
function extractLineData(buttonValue, replyText) {
  try {
    const buttonJson = JSON.parse(buttonValue);

    if (buttonJson.type === "line") {
      const plainText = convertToPlainText(replyText);
      // ここで改行コードをエスケープ
      const escapedText = plainText.replace(/\n/g, '\\n');

      return {
        user_id: buttonJson.userId || null,
        reply_token: buttonJson.replyToken,
        message_text: escapedText, // エスケープされたテキストを使用
        message_length: escapedText.length,
        ready_for_api: !!(buttonJson.replyToken && escapedText)
      };
    }
  } catch (error) {
    return {
      error: "Failed to parse LINE data",
      details: error.message
    };
  }

  return null;
}

// メッセージ内容抽出の共通関数
function extractMessageContent(messageBlocks) {
  let senderEmail = "";
  let subjectInfo = "";
  let replyText = "";

  if (messageBlocks && messageBlocks.length > 1) {
    // 送信者情報の抽出とクリーンアップ
    if (messageBlocks[1].fields && messageBlocks[1].fields[0]) {
      const rawSender = messageBlocks[1].fields[0].text.split('\n')[1] || "";

      // HTMLエンティティをデコード
      const decodedSender = rawSender
        .replace(/"/g, '')
        .replace(/&lt;/g, '<')
        .replace(/&gt;/g, '>');

      // Slackのmailtoリンク形式を処理: <mailto:email|display>
      const mailtoMatch = decodedSender.match(/<mailto:([^|]+)\|([^>]+)>/);
      if (mailtoMatch) {
        senderEmail = mailtoMatch[1];
      } else {
        // 通常の Name <email@example.com> 形式
        const emailMatch = decodedSender.match(/<([^>]+)>/);
        if (emailMatch) {
          senderEmail = emailMatch[1]; // メールアドレス部分のみ抽出
        } else {
          // メールアドレスのみの場合
          senderEmail = decodedSender.trim();
        }
      }
    }

    // 件名情報の抽出
    if (messageBlocks[1].fields && messageBlocks[1].fields[1]) {
      subjectInfo = messageBlocks[1].fields[1].text.split('\n')[1] || "";
    }

    // 返信テキストの抽出とHTML変換
    if (messageBlocks[2] && messageBlocks[2].text) {
      const fullText = messageBlocks[2].text.text;
      const replyMatch = fullText.match(/返信案:\s*(.*?)\s*$/s);
      let rawReplyText = replyMatch ? replyMatch[1].trim() : "";

      // 不要な部分を削除
      rawReplyText = rawReplyText
        .replace(/^:memo:\s*返信案:\s*/, '') // 先頭の:memo: 返信案:を削除
        .replace(/^📝\s*返信案:\s*/, '') // 先頭の📝 返信案:を削除
        .replace(/^返信案:\s*/, '') // 先頭の返信案:を削除
        .replace(/<mailto:[^>]+>\s*様\s*/g, '') // <mailto:...> 様 を削除
        .trim();

      // 改行コードをJSONで有効なエスケープシーケンスに変換
      replyText = rawReplyText
        .replace(/\r\n/g, '\\n')
        .replace(/\r/g, '\\n')
        .replace(/\n/g, '\\n');
    }
  }

  return { senderEmail, subjectInfo, replyText };
}

// 共通のレスポンス構築関数
function buildResponse(baseData, messageContent = {}) {
  const notificationType = getNotificationType(baseData.button_value);

  // 基本レスポンス
  const response = {
    // アクション情報
    action_id: baseData.action_id || null,
    button_value: baseData.button_value || null,
    type: baseData.type || null,
    notification_type: notificationType,

    // ユーザー・チャンネル情報
    user_id: baseData.user_id || null,
    channel_id: baseData.channel_id || null,
    trigger_id: baseData.trigger_id || null,
    response_url: baseData.response_url || null,

    // メッセージ情報
    id: baseData.id || null,
    sender: messageContent.senderEmail || "",
    subject: messageContent.subjectInfo || "",
    reply_text: messageContent.replyText || "",

    // view_submission特有の情報
    edited_content: baseData.edited_content || null,
    callback_id: baseData.callback_id || null,
    message_ts: baseData.message_ts || null,

    // 原本データ（必要時参照用）
    original_payload: baseData.original_payload || null,

    // GmailのURL
    gmail_url: baseData.gmail_url || null,

    // 処理時刻
    processed_at: new Date().toISOString()
  };

  // LINE用の追加処理
  if (notificationType === "line") {
    const lineData = extractLineData(baseData.button_value, messageContent.replyText);
    response.line_data = lineData;
  }

  return response;
}

// ペイロードタイプによる処理分岐
if (payload.type === 'view_submission') {
  // モーダル送信の場合
  const private_metadata = JSON.parse(payload.view.private_metadata);
  const email_id = private_metadata.email_id;
  const channel_id = private_metadata.channel_id;
  const message_ts = private_metadata.message_ts;

  // **修正箇所**：edited_contentをエスケープ
  const email_content = payload.view.state.values.email_content_block.email_content_input.value.replace(/\n/g, '\\n');

  // private_metadataに元のメッセージ情報も含まれている場合は使用
  const messageContent = {
    senderEmail: private_metadata.sender || "",
    subjectInfo: private_metadata.subject || "",
    replyText: private_metadata.reply_text || ""
  };

  const baseData = {
    action_id: "modal_submission",
    type: "view_submission",
    id: email_id,
    edited_content: email_content,
    user_id: payload.user.id,
    callback_id: payload.view.callback_id,
    channel_id: channel_id,
    message_ts: message_ts,
    original_payload: payload
  };

  return [{ json: buildResponse(baseData, messageContent) }];

} else if (payload.type === 'block_actions') {
  // ボタンクリックの場合
  const action = payload.actions && payload.actions[0];
  const messageBlocks = payload.message && payload.message.blocks;

  // メッセージ内容を抽出
  const messageContent = extractMessageContent(messageBlocks);

  const baseData = {
    action_id: action ? action.action_id : null,
    button_value: action ? action.value : null,
    type: "block_actions",
    user_id: payload.user ? payload.user.id : null,
    channel_id: payload.channel ? payload.channel.id : null,
    trigger_id: payload.trigger_id || null,
    response_url: payload.response_url || null,
    id: action ? action.value : null,
    original_payload: payload,
    gmail_url: action && action.value ?
      `https://mail.google.com/mail/u/0/#inbox/${action.value}` :
      null
  };

  return [{ json: buildResponse(baseData, messageContent) }];

} else {
  return [{
    json: {
      error: "Unknown payload type",
      type: payload.type,
      original_payload: payload
    }
  }];
}

