const trigger_id = $input.all()[0].json.trigger_id;
const email_id = $input.all()[0].json.button_value;
const channel_id = $input.all()[0].json.channel_id;
const message_ts = $input.all()[0].json.original_payload.container.message_ts;
const notification_type = $input.all()[0].json.notification_type;
const token = $env.SLACK_BOT_TOKEN;

const view = {
  type: "modal",
  callback_id: "edit_email_modal",
  private_metadata: JSON.stringify({
    email_id: email_id,
    channel_id: channel_id,
    message_ts: message_ts,
    notification_type: notification_type // ここに新しい変数を追加
  }),
  title: {
    type: "plain_text",
    text: "メール内容編集"
  },
  submit: {
    type: "plain_text",
    text: "保存"
  },
  close: {
    type: "plain_text",
    text: "キャンセル"
  },
  blocks: [
    {
      type: "input",
      block_id: "email_content_block",
      label: {
        type: "plain_text",
        text: "メール内容"
      },
      element: {
        type: "plain_text_input",
        action_id: "email_content_input",
        multiline: true,
        initial_value: $input.all()[0].json.reply_text,
        placeholder: {
          type: "plain_text",
          text: "メールの内容を入力してください"
        }
      }
    }
  ]
};

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://slack.com/api/views.open',
  headers: {
    'Authorization': `Bearer ${token}`,
    'Content-Type': 'application/json; charset=utf-8'
  },
  body: {
    trigger_id: trigger_id,
    view: view
  }
});

return [{ json: response }];

const inputData = $input.all()[0].json;
const payload = JSON.parse(inputData.body.payload);
let notificationType = null;

if (payload.type === 'view_submission') {
  const privateMetadata = JSON.parse(payload.view.private_metadata);
  notificationType = privateMetadata.notification_type;
} else if (payload.type === 'block_actions') {
  const buttonValue = JSON.parse(payload.actions[0].value);
  notificationType = buttonValue.type;
}

// 既存のすべてのデータに新しいプロパティを追加して返します
inputData.notificationType = notificationType;

return [{ json: inputData }];

const payload = $input.all()[0].json;

// view_submissionの場合の処理
if (payload.type === 'view_submission') {  
  return [{
    json: {
      id: payload.id,           // {{ $json.id }} に対応
      message_text: payload.edited_content,  // {{ $json.reply_text }} に対応
      user_id: JSON.parse(payload.id).userId,
      channel_id: payload.channel_id,
      message_ts: payload.message_ts,
      timestamp: new Date().toISOString()
    }
  }];
}

// view_submissionでない場合は空を返す
return [{ json: {} }];
